function pageInstructor():void{$u=requireUser('instructor');$list=pageQuery('SELECT COUNT(*) FROM courses WHERE instructor_id=?','SELECT c.*,g.name category_name FROM courses c JOIN categories g ON g.id=c.category_id WHERE c.instructor_id=? ORDER BY c.created_at DESC,c.id DESC',[$u['id']]);$cs=$list['rows'];?><main class="container"><?php heading(t('KHÔNG GIAN GIẢNG DẠY'),t('Khóa học của bạn'),t('Biên soạn bài học và quiz, sau đó xuất bản.'));renderInstructorInsights((int)$u['id']);?><a class="btn btn-primary mb-3" href="<?=h(url('edit'))?>"><?=h(t('+ Tạo khóa học'))?></a><div class="stats-grid"><?php statCard(t('Khóa học của bạn'),$list['total']);statCard(t('Tổng enrollment'),val('SELECT COUNT(*) FROM enrollments e JOIN courses c ON c.id=e.course_id WHERE c.instructor_id=?',[$u['id']]),t('Không phải số học viên duy nhất'));?></div><div class="panel table-responsive" tabindex="0" role="region" aria-label="<?=h(t('Danh sách quản lý, cuộn ngang khi cần'))?>"><table class="table"><thead><tr><th><?=h(t('Khóa học'))?></th><th><?=h(t('Danh mục'))?></th><th><?=h(t('Trạng thái'))?></th><th><?=h(t('Thao tác'))?></th></tr></thead><tbody><?php foreach($cs as $c):?><tr><td><strong><?=h($c['title'])?></strong></td><td><?=h($c['category_name'])?></td><td><?=statusBadge($c['status'])?></td><td><a class="btn btn-outline-secondary btn-sm" href="<?=h(url('edit',['id'=>$c['id']]))?>"><?=h(t('Quản lý →'))?></a></td></tr><?php endforeach?></tbody></table><?php if(!$cs)emptyState(t('Chưa có khóa học'));pagination($list);?></div></main><?php }
function pageEdit(int $id):void{$u=requireUser('instructor');$c=$id?ownerCourse($id):['id'=>0,'title'=>'','description'=>'','cover_key'=>'default','category_id'=>1,'status'=>'draft'];$tab=(string)($_GET['tab']??'info');if(!in_array($tab,['info','content','quiz','students'],true))$tab='info';$closed=$id&&($c['status']!=='draft'||hasEnrollment($id));?><main class="container"><a href="<?=h(url('instructor'))?>"><?=h(t('← Khóa học của bạn'))?></a><?php heading(t('BIÊN SOẠN KHÓA HỌC'),$id?$c['title']:t('Tạo bản nháp mới'),t('Lưu từng phần. Rà soát bài học và quiz trước khi xuất bản.'));if($id):?><div class="editor-actions"><?=statusBadge($c['status'])?><a class="btn btn-light" href="<?=h(url('preview',['id'=>$id]))?>"><?=h(t('Xem trước'))?></a><?php foreach(($c['status']==='draft'?['published']:($c['status']==='published'?['draft','archived']:['published'])) as $target):echo formStart('course_state',['course_id'=>$id,'target'=>$target,'return_page'=>'edit']);echo confirmField();?><button class="btn btn-outline-secondary btn-sm"><?=h(['published'=>t('Xuất bản'),'draft'=>t('Về nháp'),'archived'=>t('Lưu trữ')][$target])?></button></form><?php endforeach;if(!$closed):echo formStart('course_delete',['course_id'=>$id,'return_page'=>'edit']);echo confirmField();?><button class="btn btn-outline-danger btn-sm"><?=h(t('Xóa nháp'))?></button></form><?php endif?></div><nav class="tabs"><?php foreach(['info'=>t('Thông tin'),'content'=>t('Nội dung'),'quiz'=>t('Quiz cuối khóa'),'students'=>t('Học viên')] as $v=>$label):?><a class="<?=$tab===$v?'active':''?>" href="<?=h(url('edit',['id'=>$id,'tab'=>$v]))?>"><?=h($label)?></a><?php endforeach?></nav><?php endif;
 if(!$id||$tab==='info'):?><section class="panel editor-form"><h2><?=h(t('Thông tin khóa học'))?></h2><?=formStart('course_save',['course_id'=>$id,'return_page'=>'edit'])?><?php field('title',t('Tên khóa học'),$c['title'],'text','required minlength="5" maxlength="150"');area('description',t('Mô tả'),$c['description'],'required minlength="20" maxlength="2000" rows="4"');?><div class="form-grid"><label><?=h(t('Danh mục'))?><select class="form-select" name="category_id"><?php foreach(all('SELECT * FROM categories ORDER BY name') as $cat):?><option value="<?=$cat['id']?>" <?=(int)$c['category_id']===(int)$cat['id']?'selected':''?>><?=h($cat['name'])?></option><?php endforeach?></select></label><label><?=h(t('Ảnh bìa có sẵn'))?><select class="form-select" name="cover_key"><?php foreach(['default','web','programming','database'] as $key):?><option <?=$key===$c['cover_key']?'selected':''?>><?=h($key)?></option><?php endforeach?></select></label></div><button class="btn btn-primary"><?=h(t('Lưu thông tin'))?></button></form></section><?php if($id):renderCourseImageForm($c);endif;
 elseif($tab==='content'):
 $chapters=all('SELECT * FROM chapters WHERE course_id=? ORDER BY position,id',[$id]);$editLesson=null;if(isset($_GET['lesson'])){$editLesson=lessonCourse((int)$_GET['lesson']);if((int)$editLesson['course_id']!==$id)reject(t('Bài không thuộc khóa.'),404);}
 ?><p class="alert alert-light"><?=$closed?t('Cấu trúc đã đóng. Chỉ sửa trình bày; không đổi mục tiêu kiến thức.'):t('Bản nháp chưa enrollment được thêm/xóa/đổi thứ tự.')?></p><div class="content-editor-grid"><section class="panel"><h2><?=h(t('Chapter và lesson'))?></h2><?php foreach($chapters as $ch):?><section class="chapter-editor"><h3><?=$ch['position']?>. <?=h($ch['title'])?></h3><?=formStart('chapter_save',['course_id'=>$id,'chapter_id'=>$ch['id'],'return_page'=>'edit','return_tab'=>'content'])?><div class="form-grid"><?php field('title',t('Tên chương'),$ch['title'],'text','required minlength="2" maxlength="150"');field('position',t('Thứ tự'),(string)$ch['position'],'number','min="1" required '.($closed?'readonly':''));?></div><button class="btn btn-light btn-sm"><?=h(t('Lưu chương'))?></button></form><?php if(!$closed):echo formStart('chapter_delete',['course_id'=>$id,'chapter_id'=>$ch['id'],'return_page'=>'edit','return_tab'=>'content']);echo confirmField();?><button class="btn btn-outline-danger btn-sm"><?=h(t('Xóa chương'))?></button></form><?php endif;foreach(all('SELECT * FROM lessons WHERE chapter_id=? ORDER BY position,id',[$ch['id']]) as $l):?><div class="content-row"><span><?=$l['position']?>. <?=h($l['title'])?></span><div class="flex gap"><a class="btn btn-light btn-sm" href="<?=h(url('preview',['id'=>$id,'lesson'=>$l['id']]))?>"><?=h(t('Xem'))?></a><a class="btn btn-light btn-sm" href="<?=h(url('edit',['id'=>$id,'tab'=>'content','lesson'=>$l['id']]))?>"><?=h(t('Sửa'))?></a></div></div><?php if(!$closed):echo formStart('lesson_delete',['course_id'=>$id,'lesson_id'=>$l['id'],'return_page'=>'edit','return_tab'=>'content']);echo confirmField();?><button class="btn btn-outline-danger btn-sm"><?=h(t('Xóa bài'))?></button></form><?php endif;endforeach?></section><?php endforeach;if(!$closed):echo formStart('chapter_save',['course_id'=>$id,'return_page'=>'edit','return_tab'=>'content']);field('title',t('Tên chương mới'),'','text','required minlength="2" maxlength="150"');field('position',t('Thứ tự'),(string)(count($chapters)+1),'number','min="1" required');?><button class="btn btn-outline-secondary"><?=h(t('+ Thêm chương'))?></button></form><?php endif?></section><section class="panel"><h2><?=$editLesson?t('Sửa bài học'):t('Thêm bài học')?></h2><?php if(!$closed||$editLesson):echo formStart('lesson_save',['course_id'=>$id,'lesson_id'=>$editLesson['id']??0,'return_page'=>'edit','return_tab'=>'content']);if(!$editLesson):?><label><?=h(t('Chương'))?><select class="form-select" name="chapter_id" required><option value=""><?=h(t('Chọn chương'))?></option><?php foreach($chapters as $ch):?><option value="<?=$ch['id']?>"><?=h($ch['title'])?></option><?php endforeach?></select></label><?php endif;field('title',t('Tiêu đề'),$editLesson['title']??'','text','required minlength="2" maxlength="150"');area('body',t('Nội dung Markdown'),$editLesson['body']??'','required minlength="50" maxlength="12000" rows="10"');field('position',t('Thứ tự'),(string)($editLesson['position']??1),'number','min="1" required '.($closed?'readonly':''));field('youtube_video_id',t('YouTube ID tùy chọn'),$editLesson['youtube_video_id']??'','text','pattern="[A-Za-z0-9_-]{11}" maxlength="11"');?><button class="btn btn-primary"><?=h(t('Lưu bài học'))?></button></form><?php else:emptyState(t('Chỉ sửa bài đã có'),t('Chọn Sửa ở danh sách bên trái.'));endif?></section></div><?php
 elseif($tab==='quiz'):
 $questions=questionsFor($id);$n=max(5,min(20,(int)($_GET['count']??count($questions))));if(!$closed)while(count($questions)<$n)$questions[]=['prompt'=>'','explanation'=>'','answers'=>array_fill(0,4,['text'=>'','is_correct'=>0])];if(!$closed)$questions=array_slice($questions,0,$n);
 ?><p class="alert alert-light"><?=h(t('5–20 câu · bốn lựa chọn/câu · một đáp án đúng · đạt từ 70%.'))?> <?=$closed?t('Quiz đã khóa, chỉ xem.'):t('Lưu toàn bộ quiz trong một transaction.')?></p><?php if(!$closed):?><form method="get" action="/index.php" class="panel mb-3"><?=hidden('page','edit').hidden('id',$id).hidden('tab','quiz')?><?php field('count',t('Số câu hỏi'),(string)$n,'number','min="5" max="20" required');?><p class="small muted"><?=h(t('Lưu quiz hiện tại trước khi đổi số câu; lựa chọn này tải lại form.'))?></p><button class="btn btn-light"><?=h(t('Áp dụng số câu'))?></button></form><?=formStart('quiz_save',['course_id'=>$id,'return_page'=>'edit','return_tab'=>'quiz'])?><?php endif;foreach($questions as $i=>$q):?><fieldset class="panel question" <?=$closed?'disabled':''?>><legend><?=h(t('Câu'))?> <?=$i+1?></legend><label><?=h(t('Câu hỏi'))?><input class="form-control" name="questions[<?=$i?>][prompt]" value="<?=h($q['prompt'])?>" required minlength="5" maxlength="500"></label><?php foreach($q['answers'] as $j=>$answer):?><div class="quiz-builder-option"><label class="correct-radio"><input type="radio" name="questions[<?=$i?>][correct]" value="<?=$j?>" <?=$answer['is_correct']?'checked':''?> required> <?=h(t('Đúng'))?></label><input class="form-control" aria-label="<?=h(t('Lựa chọn {option}, câu {number}',['option'=>chr(65+$j),'number'=>$i+1]))?>" name="questions[<?=$i?>][answers][<?=$j?>]" value="<?=h($answer['text'])?>" required maxlength="250"></div><?php endforeach?><label><?=h(t('Giải thích'))?><textarea class="form-control" name="questions[<?=$i?>][explanation]" maxlength="1000"><?=h($q['explanation'])?></textarea></label></fieldset><?php endforeach;if(!$closed):?><button class="btn btn-primary"><?=h(t('Lưu toàn bộ quiz'))?></button></form><?php endif;
 elseif($tab==='students'):
 $list=pageQuery('SELECT COUNT(*) FROM enrollments e WHERE e.course_id=?','SELECT e.*,u.name,COALESCE(totals.total,0) total,COALESCE(done.done,0) done,scores.best FROM enrollments e JOIN users u ON u.id=e.user_id '.progressJoins().' WHERE e.course_id=? ORDER BY e.created_at DESC,e.id DESC',[$id]);$rows=$list['rows'];?><section class="panel table-responsive" tabindex="0" role="region" aria-label="<?=h(t('Danh sách quản lý, cuộn ngang khi cần'))?>"><h2><?=h(t('Học viên của khóa'))?></h2><table class="table"><thead><tr><th><?=h(t('Họ tên'))?></th><th><?=h(t('Tiến độ'))?></th><th><?=h(t('Điểm tốt nhất'))?></th><th><?=h(t('Hoàn thành'))?></th></tr></thead><tbody><?php foreach($rows as $e):$p=rowProgress($e);?><tr><td><?=h($e['name'])?></td><td><?=$p['percent']?>%</td><td><?=h($p['best']??'—')?></td><td><?=$e['completed_at']?t('Có'):t('Chưa')?></td></tr><?php endforeach?></tbody></table><?php if(!$rows)emptyState(t('Chưa có học viên'));pagination($list);?></section><?php endif?></main><?php }
function pagePreview(int $id):void{$u=requireUser();$c=$u['role']==='admin'?getCourse($id):ownerCourse($id);?><main class="container"><a href="<?=h(url($u['role']==='admin'?'admin':'edit',$u['role']==='admin'?['tab'=>'courses']:['id'=>$id]))?>"><?=h(t('← Về quản lý'))?></a><?php heading(t('XEM TRƯỚC CHỈ ĐỌC'),$c['title'],t('Không tạo enrollment, progress hoặc attempt.'));?><div class="panel"><?php if(isset($_GET['lesson'])){$l=lessonCourse((int)$_GET['lesson']);if((int)$l['course_id']!==$id)reject(t('Bài không thuộc khóa.'),404);lessonViewer($l);}else{foreach(courseLessons($id) as $l)echo '<p><a href="'.h(url('preview',['id'=>$id,'lesson'=>$l['id']])).'">'.h($l['title']).' →</a></p>';echo '<h2>'.h(t('Quiz và đáp án cho quản lý')).'</h2>';foreach(questionsFor($id) as $q){echo '<h3>'.h($q['prompt']).'</h3><ul>';foreach($q['answers'] as $a)echo '<li>'.h($a['text']).($a['is_correct']?' ✓':'').'</li>';echo '</ul>';}}?></div></main><?php }
function pageAdmin():void{
 requireUser('admin');$tab=(string)($_GET['tab']??'users');if(!in_array($tab,['users','courses','categories'],true))$tab='users';
 $q=searchQuery();$pattern=searchPattern($q);
 if($tab==='users'){$where="name LIKE ? ESCAPE '!' OR email LIKE ? ESCAPE '!'";$params=[$pattern,$pattern];$table='users';}
 elseif($tab==='courses'){$where="title LIKE ? ESCAPE '!'";$params=[$pattern];$table='courses';}
 else{$where="name LIKE ? ESCAPE '!'";$params=[$pattern];$table='categories';}
 $list=pageQuery('SELECT COUNT(*) FROM '.$table.' WHERE '.$where,'SELECT * FROM '.$table.' WHERE '.$where.' ORDER BY id DESC',$params);
 ?><main class="container"><?php heading(t('QUẢN TRỊ HỆ THỐNG'),t('Tổng quan StudyMate'),t('Quản lý tài khoản, trạng thái khóa học và danh mục.'));renderAdminInsights();?><div class="stats-grid"><?php statCard(t('Người dùng'),val('SELECT COUNT(*) FROM users'));statCard(t('Tổng khóa học'),val('SELECT COUNT(*) FROM courses'));statCard(t('Đã xuất bản'),val("SELECT COUNT(*) FROM courses WHERE status='published'"));?></div><nav class="tabs"><?php foreach(['users'=>t('Người dùng'),'courses'=>t('Khóa học'),'categories'=>t('Danh mục')] as $v=>$name):?><a class="<?=$v===$tab?'active':''?>" href="<?=h(url('admin',['tab'=>$v]))?>"><?=h($name)?></a><?php endforeach?></nav>
 <form class="filter-bar" method="get"><?=hidden('page','admin').hidden('tab',$tab)?><?php field('q',t('Tìm tên hoặc email'),$q,'text','maxlength="100"');?><button class="btn btn-primary"><?=h(t('Tìm'))?></button></form>
 <section class="panel table-responsive" tabindex="0" role="region" aria-label="<?=h(t('Danh sách quản lý, cuộn ngang khi cần'))?>"><table class="table"><thead><tr><th><?=$tab==='users'?t('Người dùng'):($tab==='courses'?t('Khóa học'):t('Danh mục'))?></th><th><?=h(t('Trạng thái / vai trò'))?></th><th><?=h(t('Thao tác'))?></th></tr></thead><tbody>
 <?php foreach($list['rows'] as $row):?><tr><?php if($tab==='users'):?><td><strong><?=h($row['name'])?></strong><small class="block muted"><?=h($row['email'])?></small></td><td><?=h($row['role'])?> · <?=$row['is_active']?t('Hoạt động'):t('Đã khóa')?></td><td><?php if($row['role']!=='admin'):echo formStart('user_status',['user_id'=>$row['id'],'is_active'=>$row['is_active']?0:1,'return_page'=>'admin']);echo confirmField();?><button class="btn btn-outline-secondary"><?=$row['is_active']?t('Khóa'):t('Mở khóa')?></button></form><?php else:echo t('Không cho khóa Admin');endif?></td>
 <?php elseif($tab==='courses'):?><td><?=h($row['title'])?></td><td><?=statusBadge($row['status'])?></td><td><a class="btn btn-light" href="<?=h(url('preview',['id'=>$row['id']]))?>"><?=h(t('Xem trước'))?></a><?php if($row['status']==='published'):echo formStart('course_state',['course_id'=>$row['id'],'target'=>'archived','return_page'=>'admin','return_tab'=>'courses']);echo confirmField();?><button class="btn btn-outline-secondary"><?=h(t('Lưu trữ'))?></button></form><?php endif?></td>
 <?php else:?><td><?=formStart('category_save',['category_id'=>$row['id'],'return_page'=>'admin','return_tab'=>'categories'])?><?php field('name',t('Tên danh mục'),$row['name'],'text','required minlength="2" maxlength="80"');?><button class="btn btn-light"><?=h(t('Lưu'))?></button></form><?php renderCategoryImageForm($row);?></td><td><?=h(t('Danh mục'))?></td><td><?=formStart('category_delete',['category_id'=>$row['id'],'return_page'=>'admin','return_tab'=>'categories'])?><?=confirmField()?><button class="btn btn-outline-danger"><?=h(t('Xóa'))?></button></form></td><?php endif?></tr><?php endforeach?></tbody></table>
 <?php if(!$list['rows'])emptyState(t('Không có kết quả phù hợp'),t('Thử thay đổi nội dung tìm kiếm.'));pagination($list);?></section>
 <?php if($tab==='categories'):?><section class="panel mt-3"><h2><?=h(t('Thêm danh mục'))?></h2><?=formStart('category_save',['return_page'=>'admin','return_tab'=>'categories'])?><?php field('name',t('Tên danh mục mới'),'','text','required minlength="2" maxlength="80"');?><button class="btn btn-primary"><?=h(t('Thêm danh mục'))?></button></form></section><?php endif?></main><?php }
